input.oldString:
.action-icon { display: grid; width: 43px; height: 43px; flex: 0 0 43px; place-items: center; border-radius: 14px; background: var(--orange); color: #281c16; }
    .action-icon svg { width: 20px; height: 20px; }
    .action-label { margin: 1px 0 5px; font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .13em; text-transform: uppercase; color: #ffb17e; }
    .action-title { margin: 0; font-size: 19px; font-weight: 800; letter-spacing: -.04em; }
    .action-description { margin: 5px 0 0; color: rgba(255,255,255,.62); font-size: 11px; }
    .complete-button {
      display: inline-flex; min-width: 185px; min-height: 51px; align-items: center; justify-content: center; gap: 10px;
      padding: 0 20px; border: 0; border-radius: 13px; background: var(--orange); color: #2b1d16;
      font-size: 12px; font-weight: 800; cursor: pointer; box-shadow: 0 7px 18px rgba(255,118,46,.2);
      transition: transform .18s ease, background .18s ease, box-shadow .18s ease;
    }
    .complete-button:hover:not(:disabled) { transform: translateY(-2px); background: #ff8a4b; box-shadow: 0 10px 24px rgba(255,118,46,.28); }

