    .complete-button {
      display: inline-flex; min-width: 185px; min-height: 51px; align-items: center; justify-content: center; gap: 10px;
      padding: 0 20px; border: 0; border-radius: 13px; background: #30251f; color: white;
      font-size: 12px; font-weight: 800; cursor: pointer; box-shadow: 0 7px 18px rgba(71,38,19,.17);
      transition: transform .18s ease, background .18s ease, box-shadow .18s ease;
    }
    .complete-button:hover:not(:disabled) { transform: translateY(-2px); background: #493328; box-shadow: 0 10px 24px rgba(71,38,19,.23); }

